196|/// (C3 extension) OpenRouter's vendor slugs and the class of the table whose closed model list
197|/// their model part is checked against.
198|pub(crate) const OPENROUTER_VENDORS: [(&str, &str); 9] = [
199|    ("openai", "openai"),
200|    ("anthropic", "anthropic"),
201|    ("google", "google"),
202|    ("z-ai", "zai"),
203|    ("moonshotai", "moonshot"),
204|    ("minimax", "minimax"),
205|    ("xiaomi", "xiaomi"),
206|    ("qwen", "alibaba"),
207|    ("meta-llama", "meta"),
208|];
209|
210|/// (C3 extension) The model token of an OpenRouter reviewer: `<slug>/<listed model>` when the
211|/// vendor slug is one of [`OPENROUTER_VENDORS`] and the model part EQUALS an entry of that
212|/// class's closed list (the table's own text), else `other`; `unknown` for no model.
213|pub(crate) fn openrouter_model_token(model: &str) -> String {
214|    let m = model.trim().to_lowercase();
215|    if m.is_empty() {
216|        return "unknown".to_string();
217|    }
218|    let m = m.strip_suffix("[1m]").unwrap_or(&m);
219|    let Some((slug, rest)) = m.split_once('/') else {
220|        return "other".to_string();
221|    };
222|    let Some((slug, class)) = OPENROUTER_VENDORS.iter().find(|(s, _)| *s == slug) else {
223|        return "other".to_string();
224|    };
225|    match model_token(vendor_of_class(class), rest).as_str() {
226|        "other" | "unknown" => "other".to_string(),
227|        listed => format!("{slug}/{listed}"),
228|    }
229|}
