231|/// The row of a class name (exact) - the plugin's table, plus C3's `openrouter`.
232|pub(crate) fn vendor_of_class(class: &str) -> Option<&'static Vendor> {
233|    VENDORS
234|        .iter()
235|        .find(|v| v.class == class)
236|        .or_else(|| (class == OPENROUTER.class).then_some(&OPENROUTER))
237|}
