239|/// The row of an engine (agy google, muse meta, claude anthropic); `None` for codex, http and
240|/// anything else.
241|pub(crate) fn vendor_of_engine(engine: &str) -> Option<&'static Vendor> {
242|    if engine.is_empty() || engine == "codex" {
243|        return None;
244|    }
245|    VENDORS
246|        .iter()
247|        .find(|v| !v.engine.is_empty() && v.engine == engine)
248|}
