250|/// `Get-TelemetryVendorByHost`: the row of a base URL's HOST (the host equals one of a row's hosts
251|/// or ends with `.` + one of them); `None` for any other host, an IPv6 literal or no host.
252|pub(crate) fn vendor_by_host(base_url: &str) -> Option<&'static Vendor> {
253|    let (_, host) = c3_core::config::canonical_base_url(base_url);
254|    let host = host.trim_end_matches('.');
255|    if host.is_empty() || host.starts_with('[') {
256|        return None;
257|    }
258|    VENDORS
259|        .iter()
260|        .chain(std::iter::once(&OPENROUTER))
261|        .find(|v| {
262|            v.hosts
263|                .iter()
264|                .any(|h| host == *h || host.ends_with(&format!(".{h}")))
265|        })
266|}
