290|/// `Get-TelemetryVendor` on a reviewer-shaped record: the class of `provider_config.base_url`'s
291|/// host when the record names one (every engine - the host first), else the engine's row, else
292|/// (codex) the built-in provider's row (`provider_config.builtin`); `None` (other) otherwise.
293|pub(crate) fn vendor_of_reviewer(engine: &str, provider_config: &Value) -> Option<&'static Vendor> {
294|    let engine = if engine.is_empty() { "codex" } else { engine };
295|    let base_url = provider_config
296|        .get("base_url")
297|        .and_then(|v| v.as_str())
298|        .unwrap_or("");
299|    if !base_url.is_empty() {
300|        return vendor_by_host(base_url);
301|    }
302|    if engine != "codex" {
303|        return vendor_of_engine(engine);
304|    }
305|    let builtin = provider_config
306|        .get("builtin")
307|        .and_then(|v| v.as_str())
308|        .unwrap_or("");
309|    if builtin.is_empty() {
310|        return None;
311|    }
312|    VENDORS
313|        .iter()
314|        .find(|v| !v.builtin.is_empty() && v.builtin == builtin)
315|}
