348|/// The reviewer of a ledger entry as an event carries it (`Get-TelemetryReviewerClass`) - ONE code
349|/// path for the consultation and the rating event: `(engine, provider, model)` - the engine (a
350|/// name of [`ENGINES`], else other), the vendor CLASS of the endpoint (`provider_config.base_url`'s
351|/// host, else the engine's row, else codex's built-in provider; else other), the model through
352|/// that class's closed list (`other` outside it, `unknown` without a model). The roster label and
353|/// the model as typed are never read into the event.
354|pub fn reviewer_class(entry: &LedgerEntry) -> (String, String, String) {
355|    let rev = &entry.reviewer;
356|    let engine = if rev.engine.trim().is_empty() {
357|        "codex"
358|    } else {
359|        rev.engine.trim()
360|    };
361|    let engine = if ENGINES.contains(&engine) {
362|        engine
363|    } else {
364|        "other"
365|    };
366|    let vendor = if engine == "other" {
367|        None
368|    } else {
369|        vendor_of_reviewer(engine, &rev.provider_config)
370|    };
371|    let model_raw = if rev.model.trim().is_empty() {
372|        entry.model.as_str()
373|    } else {
374|        rev.model.as_str()
375|    };
376|    (
377|        engine.to_string(),
378|        vendor.map(|v| v.class).unwrap_or("other").to_string(),
379|        model_token(vendor, model_raw),
380|    )
381|}
