395|/// `Get-TelemetryOutcome`: `(outcome, severity)` - `usable` (`usable-after-continuation` after a
396|/// timeout continuation) with `info`; else `failed:<class>` - the provider failure's class, else
397|/// from the bridge outcome (`timeout`, `stalled`, `operator` - the operator's kick -, else
398|/// `bridge`), a class outside [`FAILURE_CLASSES`] `unknown` - with `warning` for auth, quota and
399|/// operator and `error` for every other class.
400|pub fn outcome_class(entry: &LedgerEntry) -> (String, &'static str) {
401|    let bo = entry.bridge_outcome.as_str();
402|    if c3_core::health::is_usable_outcome(bo) {
403|        let o = if bo.contains("after a timeout continuation") {
404|            "usable-after-continuation"
405|        } else {
406|            "usable"
407|        };
408|        return (o.into(), "info");
409|    }
410|    let mut class = entry
411|        .provider_failure
412|        .as_ref()
413|        .map(|p| p.class.trim().to_string())
414|        .unwrap_or_default();
415|    // (wave 8 = plugin wave 30, T15) a run stopped at its quota budget is reported as the class
416|    // quota (its ledger says budget in its outcome and hint only - no new class in the contract)
417|    if bo.starts_with("failed: stopped at the quota budget") {
418|        class = "quota".into();
419|    }
420|    if class.is_empty() {
421|        class = if bo.starts_with("failed: timeout") {
422|            "timeout"
423|        } else if bo.starts_with("failed: stalled") {
424|            "stalled"
425|        } else if bo.contains("stopped by the operator") {
426|            "operator"
427|        } else {
428|            "bridge"
429|        }
430|        .into();
431|    }
432|    if !FAILURE_CLASSES.contains(&class.as_str()) {
433|        class = "unknown".into();
434|    }
435|    let sev = if ["auth", "quota", "operator"].contains(&class.as_str()) {
436|        "warning"
437|    } else {
438|        "error"
439|    };
440|    (format!("failed:{class}"), sev)
441|}
