465|/// `^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$` (lower case).
466|pub(crate) fn is_guid(v: &str) -> bool {
467|    let parts: Vec<&str> = v.split('-').collect();
468|    parts.len() == 5
469|        && [8, 4, 4, 4, 12]
470|            .iter()
471|            .zip(&parts)
472|            .all(|(n, p)| p.len() == *n && p.chars().all(|c| matches!(c, '0'..='9' | 'a'..='f')))
473|}
