151|/// An observation instant as a record stores it (wave 8i): RFC3339 with the fractional seconds it
152|/// has (`2026-10-13T12:00:00.900+00:00`; none when it has none), so it reads back exactly.
153|fn iso_instant(v: DateTime<FixedOffset>) -> String {
154|    v.to_rfc3339_opts(chrono::SecondsFormat::AutoSi, false)
155|}
156|
157|/// Compare two observation instants at WHOLE-SECOND granularity (floor to the second; fractions
158|/// are bookkeeping, never an ordering key): a strictly later second wins on recency, the same
159|/// second is a tie that [`cmp_window_rank`] decides. (floor second, then the rank) is a
160|/// lexicographic total order, so a fold over any mix of precisions is transitive and
161|/// order-independent.
162|fn cmp_instants(a: DateTime<FixedOffset>, b: DateTime<FixedOffset>) -> std::cmp::Ordering {
163|    a.timestamp().cmp(&b.timestamp())
164|}
