166|/// The keys of a recorded `quota` that carry each window's OWN observation instant (wave 8h),
167|/// primary then secondary.
168|pub const WINDOW_AT_KEYS: [&str; 2] = ["primary_observed_at", "secondary_observed_at"];
169|
170|/// One observation of the windows: the windows of one `token_count` event and when it was written.
171|#[derive(Debug, Clone, PartialEq)]
172|pub struct Observation {
173|    pub primary: Option<Window>,
174|    pub secondary: Option<Window>,
175|    /// When the observation was written; for an AGGREGATE, derived (the latest of the per-window
176|    /// instants) and for display only - never a replacement decision.
177|    pub at: Option<DateTime<FixedOffset>>,
178|    /// The instant of the primary window / of the secondary window when it differs from `at` (an
179|    /// aggregate keeps each retained window's OWN observation instant); `None` = `at`.
180|    pub primary_at: Option<DateTime<FixedOffset>>,
181|    pub secondary_at: Option<DateTime<FixedOffset>>,
182|    pub limit_id: String,
183|}
184|
185|impl Observation {
186|    /// The observation instant of ONE window (0 = primary, 1 = secondary): its own, else `at`.
187|    pub fn window_at(&self, kind: usize) -> Option<DateTime<FixedOffset>> {
188|        let own = if kind == 0 {
189|            self.primary_at
190|        } else {
191|            self.secondary_at
192|        };
193|        own.or(self.at)
194|    }
195|
196|    /// It names a window (primary or secondary).
197|    pub fn named(&self) -> bool {
198|        self.primary.is_some() || self.secondary.is_some()
199|    }
200|
201|    fn fullest(&self) -> f64 {
202|        let p = self.primary.as_ref().map(|w| w.used_percent).unwrap_or(0.0);
203|        let s = self
204|            .secondary
205|            .as_ref()
206|            .map(|w| w.used_percent)
207|            .unwrap_or(0.0);
208|        p.max(s)
209|    }
210|
211|    /// The ledger's `quota` `{primary, secondary, observed_at}` (observed_at local), then - only for
212|    /// a window that is present - `primary_observed_at` / `secondary_observed_at`: the instant
213|    /// each retained window was OBSERVED (wave 8h; `observed_at` is the derived aggregate, the
214|    /// legacy fallback of a record written without them).
215|    pub fn to_quota(&self) -> Value {
216|        let mut q = json!({
217|            "primary": self.primary.as_ref().map(Window::to_json),
218|            "secondary": self.secondary.as_ref().map(Window::to_json),
219|            "observed_at": self.at.map(|a| iso(to_local(a))),
220|        });
221|        for (kind, key) in WINDOW_AT_KEYS.iter().enumerate() {
222|            let present = if kind == 0 {
223|                self.primary.is_some()
224|            } else {
225|                self.secondary.is_some()
226|            };
227|            if let (true, Some(t)) = (present, self.window_at(kind)) {
228|                q[*key] = Value::String(iso_instant(to_local(t)));
229|            }
230|        }
231|        q
232|    }
233|}
