268|/// `Get-TelemetryModelToken`: the entry of `vendor`'s closed list the model EQUALS after
269|/// lower-casing both (and stripping a trailing `[1m]`), as the TABLE spells it; `other` for a
270|/// model outside the list or without a vendor; `unknown` for no model at all.
271|pub(crate) fn model_token(vendor: Option<&Vendor>, model: &str) -> String {
272|    let m = model.trim().to_lowercase();
273|    if m.is_empty() {
274|        return "unknown".to_string();
275|    }
276|    let Some(v) = vendor else {
277|        return "other".to_string();
278|    };
279|    if v.class == OPENROUTER.class {
280|        return openrouter_model_token(&m);
281|    }
282|    let m = m.strip_suffix("[1m]").unwrap_or(&m);
283|    v.models
284|        .iter()
285|        .find(|known| known.to_lowercase() == m)
286|        .map(|k| k.to_string())
287|        .unwrap_or_else(|| "other".to_string())
288|}
