120|/// `ConvertFrom-RolloutWindow`: an object with `used_percent`; `None` for null or a text without it.
121|fn window_of(v: &Value) -> Option<Window> {
122|    let o = v.as_object()?;
123|    let used = match o.get("used_percent")? {
124|        v @ Value::Number(_) => finite_percent(v)?,
125|        _ => return None,
126|    };
127|    let window_minutes = o.get("window_minutes").and_then(|m| {
128|        m.as_i64()
129|            .or_else(|| m.as_f64().filter(|f| *f >= 0.0).map(|f| f as i64))
130|    });
131|    let resets_at = o
132|        .get("resets_at")
133|        .and_then(|r| r.as_i64().or_else(|| r.as_f64().map(|f| f as i64)))
134|        .and_then(|secs| Utc.timestamp_opt(secs, 0).single())
135|        .map(|t| iso(t.with_timezone(&Local).fixed_offset()));
136|    Some(Window {
137|        used_percent: used,
138|        window_minutes,
139|        resets_at,
140|    })
141|}
